#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniCut Patch 38 - Effect keyframe fix, stable Effect Preview Cache, FPS counter, fast preview follow-up

* Fixes effects that disappeared when the playhead was BETWEEN two keyframes: effects.py used bezier_ease without importing it, the error was caught and the effect was skipped. Only between keys; before the first and after the last key it worked.
* Effect Preview Cache: the disk cache key contained a memory address of the effect function, so it never matched in the next run. The new key is stable (effect, default parameters, test card, size, effect source code); a changed effect is made again, only when its tile is shown. Pictures are shared by all projects; a damaged file is made again.
* Optional FPS counter on the top-left corner of the preview (Settings, off by default): FPS while playing and the last render time, green / amber / red against the target.
* Fast preview: after a slider stops, the full-quality frame is requested once. The small picture stays until it arrives (no flicker).

Files changed: minicut/render/effects.py, minicut/render/preview.py, minicut/shared/core.py, minicut/shared/dialogs.py, minicut/workspace/preview_widgets.py, minicut/workspace/viewport.py, minicut/render/fxcache.py
  python Patch/apply_38_keyframe_fix_cache_fps.py --check      (look only, change nothing)
  python Patch/apply_38_keyframe_fix_cache_fps.py              (install)
  python Patch/apply_38_keyframe_fix_cache_fps.py --revert     (put the files back from the backup)
Close MiniCut before installing. The MiniCut Launcher can do all of this for you.
"""
import base64, datetime, hashlib, json, os, py_compile, shutil, sys, zlib
PATCH_NAME = "patch38_keyframe_cache_fps"
REPLACE = {'minicut/render/effects.py': {'base': 'dedcfaf2f690cac6726d3faa61053a564eb781987c6b64d48686afce7ad7454e', 'new': '7436510fffc377cdd6e8d7ca916534fc786c933c018462745ce776a2e042ceba'}, 'minicut/render/preview.py': {'base': '7d535796e9e14954c737c322a3b10232d3106bcf54458ee036c829d1733dac55', 'new': 'ca736e7e1f1c561ee883245413ff816e45d6b4dc8334a70847c9a48c828c377d'}, 'minicut/shared/core.py': {'base': 'd837de106e5be6b927dc22eccc90f3e781330f3a6710935bf457b08d64814501', 'new': '694e582187f88d2eec44243d6e0113210fa020e368a1a894b5872a667263e8c2'}, 'minicut/shared/dialogs.py': {'base': 'd106c3f5fd6ade703f719351e1aa1cc77e14e393f154695a3207e8fbdef9f4fd', 'new': '5fd7e5dc15038a34aed3ef796bd72a8c3fb27f876f7e02c78b71b08193e20642'}, 'minicut/workspace/preview_widgets.py': {'base': '7a7e76e02a9196bce41289401ae77638b21d4c21ac2758d7aacbdae148b71c3a', 'new': 'd271d01e130de3b577e7e80b9b05a2972cb988726b823ddeebebb48db5592e2f'}, 'minicut/workspace/viewport.py': {'base': 'e363fad24e36b73f45a939e322534928b656c050d65c7a327bb6f667c7cfdbbf', 'new': '7f50f79b44f3b5f23c7b8fc214d0a18c243f0cde2f8046d3f6658c6599b881bd'}}
NEW_FILES = {'minicut/render/fxcache.py': '"""Effect Preview Cache (Patch 32 step 2).\n\nThe effect gallery shows every effect on one fixed test card (bright and dark areas, sharp edges, a gradient, colour patches)\ninstead of on the frame of the timeline.  The finished pictures are kept on disk, so they are shared by all projects and\nthe gallery opens at once.  A picture is reused only when everything that made it is the same: the effect and its default\nparameters, the test card, the size, and the effect source code.  If any of these changes the picture is made again, and\nonly when its tile is shown.  A missing or damaged file is simply made again; nothing here can stop the program.\n"""\nimport os, json, time, hashlib\nimport numpy as np\nimport cv2\n\nCACHE_VER = 1                 # raise it when the way previews are made changes\nCARD_W = 200\nBASE_W = 1920.0               # the width the effect parameters are meant for (preview k = CARD_W / BASE_W)\nMAX_BYTES = 150 * 1024 * 1024\nMAX_AGE_DAYS = 60\n\n_STATE = {"dir": None, "code": None, "card": None, "pruned": False}\n\n\ndef cache_dir():\n    if _STATE["dir"] is None:\n        base = os.path.join(os.path.expanduser("~"), ".minicut")\n        try:\n            from ..shared.core import APP_DIR; base = APP_DIR\n        except Exception: pass\n        _STATE["dir"] = os.path.join(base, "fxcache")\n    return _STATE["dir"]\n\n\ndef test_card(w=CARD_W):\n    """Fixed BGRA test picture. The same bytes every time (no random numbers)."""\n    if _STATE["card"] is not None and _STATE["card"].shape[1] == w: return _STATE["card"]\n    h = int(round(w * 9 / 16)); img = np.zeros((h, w, 4), np.uint8); img[..., 3] = 255\n    xs = np.linspace(0, 1, w, dtype=np.float32)[None, :]; ys = np.linspace(0, 1, h, dtype=np.float32)[:, None]\n    img[..., 0] = (255 * (1 - xs) * (0.4 + 0.6 * ys)).astype(np.uint8)                     # soft colour gradient (background)\n    img[..., 1] = (255 * (0.25 + 0.75 * ys) * (0.5 + 0.5 * xs)).astype(np.uint8)\n    img[..., 2] = (255 * xs * (1 - 0.5 * ys)).astype(np.uint8)\n    s = w / 200.0; S = lambda v: int(round(v * s))\n    cv2.rectangle(img, (0, 0), (S(66), h // 2), (235, 235, 235, 255), -1)                  # bright block\n    cv2.rectangle(img, (0, h // 2), (S(66), h), (18, 18, 18, 255), -1)                     # dark block\n    cv2.circle(img, (S(110), h // 2), max(4, h // 3), (250, 250, 250, 255), -1)            # sharp round edge\n    cv2.circle(img, (S(110), h // 2), max(2, h // 6), (30, 30, 200, 255), -1)\n    cv2.rectangle(img, (S(150), S(14)), (S(190), S(52)), (40, 200, 40, 255), -1)           # colour patches\n    cv2.rectangle(img, (S(158), S(24)), (S(198), S(62)), (220, 120, 20, 255), 2)\n    for i in range(6):                                                                     # fine lines (detail)\n        x0 = S(8 + i * 9); cv2.line(img, (x0, S(10)), (x0, S(40)), (20, 20, 20, 255) if i % 2 else (240, 240, 240, 255), 1)\n    cv2.line(img, (0, h - 1), (w - 1, S(60)), (255, 255, 255, 255), 1, cv2.LINE_AA)\n    _STATE["card"] = np.ascontiguousarray(img); return _STATE["card"]\n\n\ndef _code_hash():\n    """Hash of the effect source files: when they change, old pictures are not reused."""\n    if _STATE["code"] is None:\n        here = os.path.dirname(os.path.abspath(__file__)); files = [os.path.join(here, "effects.py")]\n        pack = os.path.join(here, "fxpack")\n        try: files += [os.path.join(pack, n) for n in sorted(os.listdir(pack)) if n.endswith(".py")]\n        except OSError: pass\n        h = hashlib.sha1()\n        for f in files:\n            try:\n                with open(f, "rb") as fh: h.update(fh.read().replace(b"\\r\\n", b"\\n"))\n            except OSError: h.update(b"?")\n        _STATE["code"] = h.hexdigest()\n    return _STATE["code"]\n\n\ndef effect_sig(typ, spec, defaults):\n    """Key of one preview: effect type + its default parameters + test card + size + code version."""\n    try: p = json.dumps(defaults, sort_keys=True, default=str)\n    except Exception: p = repr(defaults)\n    card = hashlib.sha1(test_card().tobytes()).hexdigest()[:12]\n    raw = "|".join([str(CACHE_VER), typ, str(spec.get("title", "")), p, card, str(CARD_W), _code_hash()])\n    return hashlib.sha1(raw.encode("utf-8", "replace")).hexdigest()\n\n\ndef _path(sig): return os.path.join(cache_dir(), sig[:2], sig + ".png")\n\n\ndef load(sig):\n    """BGRA picture from the disk cache, or None (missing or damaged file)."""\n    p = _path(sig)\n    try:\n        data = np.fromfile(p, np.uint8)\n        img = cv2.imdecode(data, cv2.IMREAD_UNCHANGED) if data.size else None\n    except Exception: return None\n    if img is None or img.ndim != 3 or img.shape[2] != 4 or img.shape[1] != CARD_W: return None\n    try: os.utime(p)                                   # used now: pruned last\n    except OSError: pass\n    return img\n\n\ndef save(sig, img):\n    """Write atomically (temp file, then rename) so a half-written file is never read."""\n    try:\n        ok, buf = cv2.imencode(".png", img)\n        if not ok: return False\n        p = _path(sig); os.makedirs(os.path.dirname(p), exist_ok=True); tmp = p + ".tmp%d" % os.getpid()\n        with open(tmp, "wb") as f: f.write(buf.tobytes())\n        os.replace(tmp, p); return True\n    except Exception: return False\n\n\ndef prune():\n    """Once per run: delete old pictures, and the oldest ones when the folder is over its size limit."""\n    if _STATE["pruned"]: return\n    _STATE["pruned"] = True\n    try:\n        items = []; now = time.time()\n        for d, _, names in os.walk(cache_dir()):\n            for n in names:\n                f = os.path.join(d, n)\n                try: st = os.stat(f)\n                except OSError: continue\n                if ".tmp" in n and now - st.st_mtime > 3600: os.remove(f); continue\n                items.append((st.st_mtime, st.st_size, f))\n        items.sort(); total = sum(i[1] for i in items)\n        for mt, sz, f in items:\n            if total <= MAX_BYTES and now - mt <= MAX_AGE_DAYS * 86400: break\n            try: os.remove(f); total -= sz\n            except OSError: pass\n    except Exception: pass\n\n\ndef render(typ):\n    """Make the preview (BGRA) of one effect with its default parameters on the test card. None when it fails."""\n    try:\n        from .effects import FX, new_effect, apply_effects\n        base = test_card()\n        out = apply_effects({"effects": [new_effect(typ)], "kind": "video"}, base.copy(), k=base.shape[1] / BASE_W, lt=0.0, fast=True)\n        if out is None or out.ndim != 3 or out.shape[1] != base.shape[1]: return None\n        if out.shape[2] == 3: out = np.dstack([out, np.full(out.shape[:2], 255, np.uint8)])\n        return np.ascontiguousarray(out)\n    except Exception as ex:\n        print("[fxcache]", typ, ex); return None\n\n\ndef get_preview(typ):\n    """(BGRA picture, from_cache). Disk first; otherwise made now and stored. (None, False) if the effect fails."""\n    try:\n        from .effects import FX, fx_defaults\n        sig = effect_sig(typ, FX[typ], fx_defaults(typ))\n    except Exception: return render(typ), False\n    img = load(sig)\n    if img is not None: return img, True\n    img = render(typ)\n    if img is not None: save(sig, img)\n    return img, False\n'}
PAYLOAD = {'minicut/render/effects.py': '', 'minicut/render/preview.py': '', 'minicut/shared/core.py': '', 'minicut/shared/dialogs.py': '', 'minicut/workspace/preview_widgets.py': '', 'minicut/workspace/viewport.py': ''}
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = HERE if os.path.isfile(os.path.join(HERE, "minicut", "app.py")) else (os.path.dirname(HERE) if os.path.isfile(os.path.join(os.path.dirname(HERE), "minicut", "app.py")) else HERE)
BACKUP_ROOT = os.path.join(ROOT, "_patch_backup")


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except OSError: return None
def new_bytes(rel):
    return zlib.decompress(base64.b64decode(PAYLOAD[rel]))
def latest_backup():
    found = []
    if os.path.isdir(BACKUP_ROOT):
        for d in os.listdir(BACKUP_ROOT):
            mf = os.path.join(BACKUP_ROOT, d, "MANIFEST.json")
            if os.path.isfile(mf):
                try:
                    with open(mf, encoding="utf-8") as f:
                        if json.load(f).get("patch") == PATCH_NAME: found.append(d)
                except Exception: pass
    return os.path.join(BACKUP_ROOT, sorted(found)[-1]) if found else None


def revert():
    bdir = latest_backup()
    if not bdir: print("No backup of this update was found."); return 1
    with open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8") as f: m = json.load(f)
    for rel in m.get("replaced", []): shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in m.get("created", []):
        try: os.remove(path_of(rel))
        except OSError: pass
    os.replace(os.path.join(bdir, "MANIFEST.json"), os.path.join(bdir, "MANIFEST.undone.json"))
    print("Reverted from backup:", bdir); return 0


def main():
    if not os.path.isfile(os.path.join(ROOT, "minicut", "app.py")):
        print("ERROR: the MiniCut folder was not found. Put this file in MiniCut/Patch/ (or next to the minicut folder)."); return 2
    if "--revert" in sys.argv: return revert()
    todo_replace, todo_new, already = [], [], 0
    for rel, h in REPLACE.items():
        cur = read(rel)
        if cur is None: print("STOPPED: missing file", rel, "- no files were changed."); return 3
        c = norm_hash(cur)
        if c == h["new"]: already += 1
        elif c == h["base"]: todo_replace.append(rel)
        else:
            print("STOPPED:", rel, "is not the version this update expects (it was changed by hand or by another update).")
            print("No files were changed. This protects your own edits."); return 3
    for rel, text in NEW_FILES.items():
        cur = read(rel)
        if cur is None: todo_new.append(rel)
        elif norm_hash(cur) == norm_hash(text.encode("utf-8")): already += 1
        else: print("STOPPED:", rel, "already exists with other content. No files were changed."); return 3
    if not todo_replace and not todo_new: print("This update is already installed."); return 0
    if "--check" in sys.argv:
        print("Check passed. Would change:", ", ".join(todo_replace + todo_new)); return 0
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); k = 1
    while os.path.exists(bdir): k += 1; bdir = os.path.join(BACKUP_ROOT, "%s_%d" % (stamp, k))      # two installs in one second
    os.makedirs(bdir, exist_ok=False)
    for rel in todo_replace:
        dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(path_of(rel), dst)
    with open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8") as f:
        json.dump({"patch": PATCH_NAME, "created": todo_new, "replaced": todo_replace}, f, indent=2)
    try:
        for rel in todo_replace:
            cur = read(rel); data = new_bytes(rel).replace(b"\r\n", b"\n")
            if b"\r\n" in cur: data = data.replace(b"\n", b"\r\n")            # keep the file's own line endings
            with open(path_of(rel), "wb") as f: f.write(data)
            if norm_hash(read(rel)) != REPLACE[rel]["new"]: raise RuntimeError("hash mismatch after writing " + rel)
        for rel in todo_new:
            os.makedirs(os.path.dirname(path_of(rel)), exist_ok=True)
            with open(path_of(rel), "wb") as f: f.write(NEW_FILES[rel].encode("utf-8"))
        for rel in todo_replace + todo_new:
            if rel.endswith(".py"): py_compile.compile(path_of(rel), doraise=True)
    except Exception as ex:
        for rel in todo_replace: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
        for rel in todo_new:
            try: os.remove(path_of(rel))
            except OSError: pass
        print("ERROR: the update failed and every file was put back:", repr(ex)); return 1
    print("Installed Patch 38. Changed:", ", ".join(todo_replace + todo_new)); print("Backup:", bdir); return 0


if __name__ == "__main__":
    try: code = main()
    except Exception as ex: print("Unexpected error:", repr(ex)); code = 1
    sys.exit(code)
